SELECT CAST([], 'Array(Tuple(String, String))') AS tags, fromUnixTimestamp64Milli({evaluation_ms:Int64}) AS timestamp, if(count() = 1, any(value), nan) AS value FROM (
    SELECT series.tags AS tags, max(d.timestamp) AS timestamp, argMax(d.value, d.timestamp) AS value FROM timeSeriesData(`observability`.`prometheus`) AS d INNER JOIN (
        SELECT DISTINCT src.id, arrayConcat([tuple('__name__', src.metric_name)], arrayMap((k, v) -> tuple(k, v), mapKeys(src.tags), mapValues(src.tags))) AS tags FROM timeSeriesTags(`observability`.`prometheus`) AS src WHERE src.metric_name = {scalar_child_instant_matcher_0_value:String} AND src.tags[concat('', {scalar_child_instant_matcher_1_key:String})] = {scalar_child_instant_matcher_1_value:String} AND src.max_time >= fromUnixTimestamp64Milli({scalar_child_required_start_ms:Int64}) AND src.min_time <= fromUnixTimestamp64Milli({scalar_child_required_end_ms:Int64})
    ) AS series ON d.id = series.id WHERE d.timestamp >= fromUnixTimestamp64Milli({scalar_child_required_start_ms:Int64}) AND d.timestamp <= fromUnixTimestamp64Milli({scalar_child_required_end_ms:Int64}) AND d.id IN (SELECT id FROM (
        SELECT DISTINCT src.id, arrayConcat([tuple('__name__', src.metric_name)], arrayMap((k, v) -> tuple(k, v), mapKeys(src.tags), mapValues(src.tags))) AS tags FROM timeSeriesTags(`observability`.`prometheus`) AS src WHERE src.metric_name = {scalar_child_instant_matcher_0_value:String} AND src.tags[concat('', {scalar_child_instant_matcher_1_key:String})] = {scalar_child_instant_matcher_1_value:String} AND src.max_time >= fromUnixTimestamp64Milli({scalar_child_required_start_ms:Int64}) AND src.min_time <= fromUnixTimestamp64Milli({scalar_child_required_end_ms:Int64})
    )) GROUP BY d.id, series.tags HAVING NOT isNaN(value) ORDER BY tags
) AS scalar_child
SETTINGS allow_experimental_time_series_table = 1
FORMAT JSONEachRow
